ValidationRule.errorConditionFormula:
ISNEW() && ISPICKVAL(AccountSource, '') 

/* Users who can bypass this validation */
&& ($User.FirstName & ' ' & $User.LastName) != 'Natasha Selvey'

/* Lead Source Detail that can bypass this validation */
&& AND(
  Lead_Source_Detail__c != 'Cognism',
  Lead_Source_Detail__c != 'Zoominfo')

/* Account Type that can bypass this validation */
&& NOT(ISPICKVAL(Type, 'Competitor'))
